//! Checks the generators against `fixtures/golden/`, generated by the TypeScript implementation
//! (`npm run gen_golden`).

use std::path::{Path, PathBuf};

use auto_composer::generator::tune as tune_generator;
use auto_composer::random::ReliableRandomFactory;
use auto_composer::snapshot::TuneSnapshot;
use serde::Deserialize;

fn golden_dir(sub: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../fixtures/golden")
        .join(sub)
}

/// The cases of a subdirectory, sorted by file name.
fn load_cases<T: for<'de> Deserialize<'de>>(sub: &str) -> Vec<(String, T)> {
    let mut paths: Vec<PathBuf> = std::fs::read_dir(golden_dir(sub))
        .expect("read the golden directory")
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|e| e == "json"))
        .collect();
    paths.sort();
    paths
        .into_iter()
        .map(|p| {
            let name = p.file_name().unwrap().to_string_lossy().into_owned();
            let text = std::fs::read_to_string(&p).unwrap();
            let case = serde_json::from_str(&text).unwrap_or_else(|e| panic!("{name}: {e}"));
            (name, case)
        })
        .collect()
}

#[derive(Deserialize)]
struct TuneCase {
    params: tune_generator::Parameters,
    expected: TuneSnapshot,
}

#[test]
fn golden_tune() {
    let cases: Vec<(String, TuneCase)> = load_cases("tune");
    assert!(!cases.is_empty());
    let failed: Vec<&str> = cases
        .iter()
        .filter(|(name, c)| {
            let tune = tune_generator::generate(&c.params, &ReliableRandomFactory)
                .unwrap_or_else(|e| panic!("{name}: {e}"));
            let actual = TuneSnapshot::from(&tune);
            if actual != c.expected {
                eprintln!("{name}: mismatch");
                for key in ["cadence", "chord", "notes"] {
                    let a = serde_json::to_value(&actual).unwrap()[key].clone();
                    let e = serde_json::to_value(&c.expected).unwrap()[key].clone();
                    if a != e {
                        eprintln!("  {key} differs");
                    }
                }
                true
            } else {
                false
            }
        })
        .map(|(name, _)| name.as_str())
        .collect();
    assert!(
        failed.is_empty(),
        "{} of {} cases failed: {failed:?}",
        failed.len(),
        cases.len()
    );
}
